#define CONFIG_LIMIT 65536u
#define CORE_PATH_LIMIT 1024u
static void err(seedless_config_error_t*e,int code,int se,const char*k,const char*m){if(!e)return;memset(e,0,sizeof*e);e->code=code;e->system_errno=se;if(k)snprintf(e->key,sizeof e->key,"%s",k);if(m)snprintf(e->message,sizeof e->message,"%s",m);}
static char *copy_string(const char*s){return s?strdup(s):NULL;}
void seedless_config_init(seedless_config_t*c){if(c)memset(c,0,sizeof*c);}
void seedless_config_free(seedless_config_t*c){if(!c)return;free(c->firmware.bios_arm7);free(c->firmware.bios_arm9);free(c->firmware.firmware_path);free(c->user.nickname);free(c->emulation.save_dir);free(c->selected_path);memset(c,0,sizeof*c);}
void seedless_runtime_config_free(seedless_runtime_config_t*r){if(!r)return;free(r->rom_path);free(r->config_path);free(r->bios_arm7);free(r->bios_arm9);free(r->firmware_path);free(r->save_dir);free(r->save_path);memset(r,0,sizeof*r);}
static int setstr(char**dst,const seedless_json_value_t*v,const char*k,seedless_config_error_t*e,int allow_empty){if(!v||v->type!=SEEDLESS_JSON_STRING||(!allow_empty&&!v->as.string[0])){err(e,1,0,k,"expected string value");return 0;}*dst=copy_string(v->as.string);if(!*dst){err(e,1,ENOMEM,k,"out of memory");return 0;}return 1;}
static int uintval(const seedless_json_value_t*v,unsigned lo,unsigned hi,unsigned*out,const char*k,seedless_config_error_t*e){if(!v||v->type!=SEEDLESS_JSON_INTEGER||v->as.integer<(int64_t)lo||v->as.integer>(int64_t)hi){err(e,1,0,k,"expected integer in supported range");return 0;}*out=(unsigned)v->as.integer;return 1;}
static int boolval(const seedless_json_value_t*v,int*out,const char*k,seedless_config_error_t*e){if(!v||v->type!=SEEDLESS_JSON_BOOL){err(e,1,0,k,"expected boolean");return 0;}*out=v->as.boolean;return 1;}
static int object_keys(const seedless_json_value_t*v,const char*const*keys,size_t n,const char*prefix,seedless_config_error_t*e){if(!v||v->type!=SEEDLESS_JSON_OBJECT){err(e,1,0,prefix,"expected object");return 0;}for(seedless_json_member_t*m=v->members;m;m=m->next){int found=0;for(size_t i=0;i<n;i++)if(!strcmp(m->key,keys[i]))found=1;if(!found){char key[96];snprintf(key,sizeof key,"%s.%s",prefix,m->key);err(e,1,0,key,"unknown setting");return 0;}}return 1;}
static int has_all(const seedless_json_value_t*v,const char*const*keys,size_t n,const char*prefix,seedless_config_error_t*e){for(size_t i=0;i<n;i++)if(!seedless_json_get(v,keys[i])){char k[96];snprintf(k,sizeof k,"%s.%s",prefix,keys[i]);err(e,1,0,k,"required setting is missing");return 0;}return 1;}
static int utf8_to_utf16(const char*s,uint16_t*out,size_t*units){size_t n=0;const unsigned char*p=(const unsigned char*)s;while(*p){uint32_t cp;unsigned more;if(*p<0x80){cp=*p++;}else if(*p>=0xc2&&*p<=0xdf){cp=*p++&31;more=1;goto cont;}else if(*p>=0xe0&&*p<=0xef){cp=*p++&15;more=2;goto cont;}else if(*p>=0xf0&&*p<=0xf4){cp=*p++&7;more=3;goto cont;}else return 0;goto emit;cont:for(unsigned i=0;i<more;i++){if((*p&0xc0)!=0x80)return 0;cp=(cp<<6)|(*p++&63);}if((more==2&&cp<0x800)||(more==3&&cp<0x10000)||(cp>=0xd800&&cp<=0xdfff)||cp>0x10ffff)return 0;emit:if(cp<=0xffff){if(n>=10)return 0;out[n++]=(uint16_t)cp;}else{if(n+2>10)return 0;cp-=0x10000;out[n++]=(uint16_t)(0xd800+(cp>>10));out[n++]=(uint16_t)(0xdc00+(cp&1023));}}*units=n;return n>0;}
static int validate_config(seedless_config_t*c,const seedless_json_value_t*root,seedless_config_error_t*e){static const char*const top[]={"visuals","firmware","user","emulation"};static const char*const vk[]={"threaded_3d","thread_count","disable_edge_marking","fix_main_screen","auto_trim"};static const char*const fk[]={"bios_arm7","bios_arm9","firmware_path"};static const char*const uk[]={"nickname","birthday_month","birthday_day","color"};static const char*const ek[]={"save_dir"};if(!object_keys(root,top,4,"config",e)||!has_all(root,top,4,"config",e))return 0;const seedless_json_value_t*v=seedless_json_get(root,"visuals"),*f=seedless_json_get(root,"firmware"),*u=seedless_json_get(root,"user"),*em=seedless_json_get(root,"emulation");if(!object_keys(v,vk,5,"visuals",e)||!has_all(v,vk,5,"visuals",e)||!object_keys(f,fk,3,"firmware",e)||!has_all(f,fk,3,"firmware",e)||!object_keys(u,uk,4,"user",e)||!has_all(u,uk,4,"user",e)||!object_keys(em,ek,1,"emulation",e)||!has_all(em,ek,1,"emulation",e))return 0;
 if(!boolval(seedless_json_get(v,"threaded_3d"),&c->visuals.threaded_3d,"visuals.threaded_3d",e)||!uintval(seedless_json_get(v,"thread_count"),0,15,&c->visuals.thread_count,"visuals.thread_count",e)||!boolval(seedless_json_get(v,"disable_edge_marking"),&c->visuals.disable_edge_marking,"visuals.disable_edge_marking",e)||!boolval(seedless_json_get(v,"fix_main_screen"),&c->visuals.fix_main_screen,"visuals.fix_main_screen",e)||!boolval(seedless_json_get(v,"auto_trim"),&c->visuals.auto_trim,"visuals.auto_trim",e))return 0;
 if(!setstr(&c->firmware.bios_arm7,seedless_json_get(f,"bios_arm7"),"firmware.bios_arm7",e,0)||!setstr(&c->firmware.bios_arm9,seedless_json_get(f,"bios_arm9"),"firmware.bios_arm9",e,0)||!setstr(&c->firmware.firmware_path,seedless_json_get(f,"firmware_path"),"firmware.firmware_path",e,1))return 0;
 if(c->firmware.bios_arm7[0]!='/'||c->firmware.bios_arm9[0]!='/'||(c->firmware.firmware_path[0]&&c->firmware.firmware_path[0]!='/')){err(e,1,0,"firmware","BIOS and nonempty firmware paths must be absolute");return 0;}
 if(!setstr(&c->user.nickname,seedless_json_get(u,"nickname"),"user.nickname",e,0)||!utf8_to_utf16(c->user.nickname,c->user.nickname_utf16,&c->user.nickname_units)){err(e,1,0,"user.nickname","nickname must fit 10 UTF-16 code units");return 0;}
 if(!uintval(seedless_json_get(u,"birthday_month"),1,12,&c->user.birthday_month,"user.birthday_month",e)||!uintval(seedless_json_get(u,"birthday_day"),1,31,&c->user.birthday_day,"user.birthday_day",e)||!uintval(seedless_json_get(u,"color"),0,15,&c->user.color,"user.color",e))return 0;
 static const unsigned days[]={0,31,29,31,30,31,30,31,31,30,31,30,31};if(c->user.birthday_day>days[c->user.birthday_month]){err(e,1,0,"user.birthday_day","day is invalid for selected month");return 0;}
 if(!setstr(&c->emulation.save_dir,seedless_json_get(em,"save_dir"),"emulation.save_dir",e,1))return 0;
 const char*paths[]={c->firmware.bios_arm7,c->firmware.bios_arm9,c->firmware.firmware_path,c->emulation.save_dir};for(size_t i=0;i<4;i++)if(strlen(paths[i])>=CORE_PATH_LIMIT){err(e,1,0,"paths","path exceeds core path limit");return 0;}return 1;}
static char *default_config_text(const char*home){char a[CORE_PATH_LIMIT*6],b[CORE_PATH_LIMIT*6];char p7[CORE_PATH_LIMIT],p9[CORE_PATH_LIMIT];if(snprintf(p7,sizeof p7,"%s/.config/seedlessds/bios/drastic_bios_arm7.bin",home)>=(int)sizeof p7||snprintf(p9,sizeof p9,"%s/.config/seedlessds/bios/drastic_bios_arm9.bin",home)>=(int)sizeof p9)return NULL;size_t n;if(!seedless_json_write_string(p7,a,sizeof a,&n)||!seedless_json_write_string(p9,b,sizeof b,&n))return NULL;const char*fmt="{\n  \"visuals\": {\"threaded_3d\": false, \"thread_count\": 0, \"disable_edge_marking\": false, \"fix_main_screen\": false, \"auto_trim\": false},\n  \"firmware\": {\"bios_arm7\": %s, \"bios_arm9\": %s, \"firmware_path\": \"\"},\n  \"user\": {\"nickname\": \"SEEDLESS\", \"birthday_month\": 3, \"birthday_day\": 2, \"color\": 0},\n  \"emulation\": {\"save_dir\": \"\"}\n}\n";int z=snprintf(NULL,0,fmt,a,b);if(z<0||z>(int)CONFIG_LIMIT)return NULL;char*out=malloc((size_t)z+1);if(out)snprintf(out,(size_t)z+1,fmt,a,b);return out;}
static int mkdir_parents(const char*path){char*copy=strdup(path);if(!copy)return 0;for(char*p=copy+1;;p++){if(*p!='/'&&*p!='\0')continue;char saved=*p;*p='\0';if(copy[0]&&mkdir(copy,0700)&&errno!=EEXIST){free(copy);return 0;}if(copy[0]){struct stat st;if(stat(copy,&st)||!S_ISDIR(st.st_mode)){free(copy);errno=ENOTDIR;return 0;}}if(!saved)break;*p=saved;}free(copy);return 1;}
static char*absolute_path(const char*p){if(!p||!*p)return NULL;char*r=realpath(p,NULL);if(r)return r;if(p[0]=='/')return strdup(p);char*cwd=getcwd(NULL,0);if(!cwd)return NULL;size_t n=strlen(cwd)+strlen(p)+2;char*q=malloc(n);if(q)snprintf(q,n,"%s/%s",cwd,p);free(cwd);return q;}
static int read_file(const char*path,char**buf,size_t*len,seedless_config_error_t*e){int fd=open(path,O_RDONLY|O_CLOEXEC|O_NONBLOCK|O_NOFOLLOW);if(fd<0){err(e,2,errno,NULL,"cannot open configuration");return 0;}struct stat st;if(fstat(fd,&st)||!S_ISREG(st.st_mode)){int se=errno?errno:EINVAL;close(fd);err(e,2,se,NULL,"configuration is not a regular file");return 0;}if(st.st_size<0||st.st_size>CONFIG_LIMIT){close(fd);err(e,2,EFBIG,NULL,"configuration exceeds 64 KiB");return 0;}size_t cap=(size_t)st.st_size+1;if(cap<1024)cap=1024;char*b=malloc(cap);if(!b){close(fd);err(e,2,ENOMEM,NULL,"out of memory");return 0;}size_t n=0;for(;;){if(n==cap-1){if(n>=CONFIG_LIMIT){char extra;ssize_t more;do{more=read(fd,&extra,1);}while(more<0&&errno==EINTR);if(more>0){free(b);close(fd);err(e,2,EFBIG,NULL,"configuration exceeds 64 KiB");return 0;}if(more<0){int se=errno;free(b);close(fd);err(e,2,se,NULL,"cannot read configuration");return 0;}break;}size_t nc=cap*2;if(nc>CONFIG_LIMIT+1)nc=CONFIG_LIMIT+1;char*t=realloc(b,nc);if(!t){free(b);close(fd);err(e,2,ENOMEM,NULL,"out of memory");return 0;}b=t;cap=nc;}ssize_t z=read(fd,b+n,cap-1-n);if(z<0&&errno==EINTR)continue;if(z<0){int se=errno;free(b);close(fd);err(e,2,se,NULL,"cannot read configuration");return 0;}if(!z)break;n+=(size_t)z;}close(fd);b[n]=0;*buf=b;*len=n;return 1;}
static int create_default(const char*path,const char*text,seedless_config_error_t*e){char*copy=strdup(path);if(!copy){err(e,3,ENOMEM,NULL,"out of memory");return 0;}char*slash=strrchr(copy,'/');if(slash){if(slash==copy)slash[1]=0;else *slash=0;if(!mkdir_parents(copy)){int se=errno;free(copy);err(e,3,se,NULL,"cannot create configuration directory");return 0;}}free(copy);size_t n=strlen(path)+16;char*tmp=malloc(n);if(!tmp){err(e,3,ENOMEM,NULL,"out of memory");return 0;}snprintf(tmp,n,"%s.tmp.XXXXXX",path);int fd=mkstemp(tmp);if(fd<0){int se=errno;free(tmp);err(e,3,se,NULL,"cannot create temporary configuration");return 0;}fchmod(fd,0600);size_t len=strlen(text),off=0;while(off<len){ssize_t z=write(fd,text+off,len-off);if(z<0&&errno==EINTR)continue;if(z<=0){int se=errno?errno:EIO;close(fd);unlink(tmp);free(tmp);err(e,3,se,NULL,"cannot write default configuration");return 0;}off+=(size_t)z;}int sync_error=fsync(fd);int sync_errno=errno;int close_error=close(fd);if(sync_error||close_error){int se=sync_error?sync_errno:errno;unlink(tmp);free(tmp);err(e,3,se,NULL,"cannot sync default configuration");return 0;}if(link(tmp,path)){int se=errno;unlink(tmp);free(tmp);if(se==EEXIST)return 2;err(e,3,se,NULL,"cannot publish default configuration");return 0;}unlink(tmp);free(tmp);return 1;}
int seedless_config_load_or_create(seedless_config_t*c,const char*override,seedless_config_error_t*e){if(!c){err(e,1,EINVAL,NULL,"invalid config output");return 0;}seedless_config_free(c);char*path=NULL;const char*home=getenv("HOME");if(override)path=absolute_path(override);else if(home&&home[0]=='/'){size_t n=strlen(home)+sizeof "/.config/seedlessds/config.json";path=malloc(n);if(path)snprintf(path,n,"%s/.config/seedlessds/config.json",home);}if(!path){err(e,1,EINVAL,NULL,override?"cannot resolve custom config path":"HOME is unavailable for default configuration");return 0;}c->selected_path=path;char*buf=NULL;size_t len=0;if(!read_file(path,&buf,&len,e)){if(e&&e->system_errno==ENOENT){fprintf(stderr,"seedlessds[warning]: configuration missing: %s\n",path);if(!home||home[0]!='/'){err(e,3,EINVAL,NULL,"HOME required to generate default BIOS paths");return 0;}char*text=default_config_text(home);if(!text){err(e,3,ENAMETOOLONG,NULL,"default BIOS path is too long");return 0;}int made=create_default(path,text,e);free(text);if(!made)return 0;if(made==2){if(!read_file(path,&buf,&len,e))return 0;}else if(!read_file(path,&buf,&len,e))return 0;}else return 0;}seedless_json_doc_t doc={0};char why[192];if(!seedless_json_parse(buf,len,&doc,why,sizeof why)){free(buf);err(e,1,0,NULL,why);return 0;}free(buf);int ok=validate_config(c,doc.root,e);seedless_json_free(&doc);if(!ok)return 0;return 1;}
static int check_bios(const char*p,off_t size){struct stat st;return stat(p,&st)==0&&S_ISREG(st.st_mode)&&st.st_size==size&&access(p,R_OK)==0;}
static int mkdir_one(const char*p){if(!mkdir_parents(p))return 0;struct stat st;return stat(p,&st)==0&&S_ISDIR(st.st_mode)&&access(p,W_OK|X_OK)==0;}
int seedless_config_resolve(seedless_config_t*c,const char*rom,const seedless_launch_options_t*o,seedless_runtime_config_t*r,seedless_config_error_t*e){if(!c||!rom||!o||!r)return 0;seedless_runtime_config_free(r);r->rom_path=realpath(rom,NULL);if(!r->rom_path){err(e,4,errno,"rom","cannot resolve ROM path");return 0;}struct stat st;if(stat(r->rom_path,&st)||!S_ISREG(st.st_mode)||access(r->rom_path,R_OK)){err(e,4,errno?errno:EINVAL,"rom","ROM must be a readable regular file");return 0;}r->config_path=copy_string(c->selected_path);r->bios_arm7=copy_string(c->firmware.bios_arm7);r->bios_arm9=copy_string(c->firmware.bios_arm9);r->firmware_path=copy_string(c->firmware.firmware_path);char*save=o->have_save_dir?copy_string(o->save_dir):copy_string(c->emulation.save_dir);if(!r->config_path||!r->bios_arm7||!r->bios_arm9||!r->firmware_path||!save){free(save);err(e,4,ENOMEM,NULL,"out of memory");return 0;}if(!check_bios(r->bios_arm7,16384)){free(save);err(e,4,errno,"firmware.bios_arm7","BIOS must be readable regular file with size 16384");return 0;}if(!check_bios(r->bios_arm9,4096)){free(save);err(e,4,errno,"firmware.bios_arm9","BIOS must be readable regular file with size 4096");return 0;}char*parent=strdup(r->rom_path);if(!parent){free(save);err(e,4,ENOMEM,NULL,"out of memory");return 0;}char*slash=strrchr(parent,'/');if(slash==parent)slash[1]=0;else *slash=0;if(!*save){r->save_dir=strdup(parent);}else r->save_dir=absolute_path(save);free(save);if(!r->save_dir){free(parent);err(e,4,ENOMEM,"emulation.save_dir","cannot resolve save directory");return 0;}if(!mkdir_one(r->save_dir)){int se=errno;free(parent);err(e,4,se,"emulation.save_dir","cannot create or use save directory");return 0;}const char*base=strrchr(r->rom_path,'/');base=base?base+1:r->rom_path;size_t bl=strlen(base);char*name=strdup(base);if(!name){free(parent);err(e,4,ENOMEM,NULL,"out of memory");return 0;}if(bl>=4&&!strcmp(name+bl-4,".nds"))name[bl-4]=0;size_t n=strlen(r->save_dir)+strlen(name)+7;r->save_path=malloc(n);if(r->save_path)snprintf(r->save_path,n,"%s/%s.sav",r->save_dir,name);free(name);free(parent);if(!r->save_path||strlen(r->save_path)>=CORE_PATH_LIMIT){err(e,4,ENAMETOOLONG,"emulation.save_dir","save path exceeds core path capacity");return 0;}return 1;}
